// This file was generated by Prisma, and assumes you have installed the following:
// npm install --save-dev prisma dotenv
import "dotenv/config";
import { defineConfig } from "prisma/config";
import { ehDevDeclarado, ehProducao } from "./lib/ambiente";

// --- Trava de segurança: nenhum comando destrutivo no banco de produção ---
//
// Dev e produção compartilharam o mesmo banco Neon até 31/07/2026, e foi assim
// que a produção quebrou: um `prisma migrate` rodado na máquina de
// desenvolvimento alterou o schema da loja em funcionamento, sem deploy nenhum.
// Ver CLAUDE.md → "Regras permanentes" e "Ambientes de banco".
//
// A Prisma CLI carrega este arquivo em TODO comando, então aqui é o único ponto
// que pega até `npx prisma migrate dev` digitado direto no terminal.
//
// Só três comandos são bloqueados — os que reescrevem ou apagam schema num
// fluxo de desenvolvimento. `generate`, `validate`, `studio` e principalmente
// `migrate deploy` passam intactos: `generate` roda no `postinstall` e
// `migrate deploy` é como a produção aplica migration no build da Vercel.
// Bloquear qualquer um dos dois derrubaria `npm install` e todo deploy.
const COMANDOS_BLOQUEADOS = [
  ["migrate", "dev"],
  ["migrate", "reset"],
  ["db", "push"],
];

function comandoBloqueado(): string | null {
  const args = process.argv.slice(2).filter((a) => !a.startsWith("-"));
  for (const alvo of COMANDOS_BLOQUEADOS) {
    if (alvo.every((parte, i) => args[i] === parte)) return alvo.join(" ");
  }
  return null;
}

function recusar(comando: string, motivo: string, comoResolver: string): never {
  console.error(
    [
      "",
      "  ┌──────────────────────────────────────────────────────────────┐",
      "  │  BLOQUEADO: comando destrutivo fora de um banco de dev        │",
      "  └──────────────────────────────────────────────────────────────┘",
      "",
      `  Comando : prisma ${comando}`,
      `  Motivo  : ${motivo}`,
      "",
      `  ${comoResolver}`,
      "",
      "  Se a intenção era aplicar uma migration EM PRODUÇÃO, o comando",
      "  certo é `prisma migrate deploy` (não bloqueado) — mas o normal é",
      "  deixar isso para o build da Vercel.",
      "",
      "  Detalhes em CLAUDE.md → \"Ambientes de banco\".",
      "",
    ].join("\n")
  );
  process.exit(1);
}

function protegerProducao(): void {
  const comando = comandoBloqueado();
  if (!comando) return;

  // Camada 1 (pega o caso mais grave): a URL é reconhecidamente a produção.
  if (ehProducao()) {
    recusar(
      comando,
      "DATABASE_URL aponta para o banco de PRODUÇÃO da loja.",
      "Aponte o .env para uma branch de dev da Neon antes de continuar."
    );
  }

  // Camada 2 (fecha por padrão): sem o marcador explícito, não roda. Assim uma
  // URL de produção nova, ou copiada da Vercel para um .env qualquer, também é
  // barrada — a Vercel nunca define AMBIENTE.
  if (!ehDevDeclarado()) {
    recusar(
      comando,
      "o .env não declara AMBIENTE=dev.",
      "Confirme que DATABASE_URL é uma branch de dev e acrescente AMBIENTE=dev ao .env."
    );
  }
}

protegerProducao();

export default defineConfig({
  schema: "prisma/schema.prisma",
  migrations: {
    path: "prisma/migrations",
    seed: "tsx prisma/seed.ts",
  },
  datasource: {
    url: process.env["DATABASE_URL"],
  },
});
